58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        prepareNewOwner(ownerFieldsDto);
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (owner.getRegistrationDate() == null) {
113	            owner.setRegistrationDate(LocalDate.now());
114	        }
115	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
116	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
117	        assignHousehold(owner, ownerFieldsDto);
118	        this.clinicService.saveOwner(owner);
119	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	        headers.setLocation(UriComponentsBuilder.newInstance()
121	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
122	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
128	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
129	        if (currentOwner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        currentOwner.setAddress(ownerFieldsDto.getAddress());
133	        currentOwner.setCity(ownerFieldsDto.getCity());
134	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
135	        currentOwner.setLastName(ownerFieldsDto.getLastName());
136	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
137	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
138	        this.clinicService.saveOwner(currentOwner);
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Transactional
144	    @Override
145	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
146	        Owner owner = this.clinicService.findOwnerById(ownerId);
147	        if (owner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        this.clinicService.deleteOwner(owner);
151	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
152	    }
