206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner != null) {
211	            Pet pet = owner.getPet(petId);
212	            if (pet != null) {
213	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
214	            }
215	        }
216	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	    }
218	
219	    /**
220	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
221	     * The address is normalized in place (so a required-field check that follows rejects an
222	     * address blank after normalization), the required fields are checked, the telephone and
223	     * email are normalized in place, and the resulting telephone is rejected when it already
224	     * belongs to another owner. Each rule
225	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
226	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
227	     * to be mapped and saved.
228	     *
229	     * @param ownerFieldsDto the submitted owner fields, normalized in place
230	     */
231	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
232	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
233	        validateRequiredFields(ownerFieldsDto);
234	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
235	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
236	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
237	        rejectDuplicateHousehold(ownerFieldsDto);
238	    }
239	
240	    /**
241	     * Builds the customer code assigned to a newly created owner. The code is formatted as
242	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
243	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
244	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
245	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
246	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
247	     *
248	     * @param city the owner's city
249	     * @param lastName the owner's last name
250	     * @return the formatted customer code
251	     */
252	    private String nextCustomerCode(String city, String lastName) {
253	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
254	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
255	        long sequence = this.clinicService.findAllOwners().stream()
256	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
257	            .count() + 1L;
258	        return String.format("%s-%s-%04d", city3, last3, sequence);
259	    }
260	
261	    /**
262	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
263	     * with the owner being created, compared case-insensitively. The count is taken before the
264	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
265	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
266	     *
267	     * @param firstName the first name of the owner being created
268	     * @param lastName the last name of the owner being created
269	     * @return the number of pre-existing owners sharing the same first and last name
270	     */
271	    private int countNamesakes(String firstName, String lastName) {
272	        return (int) this.clinicService.findAllOwners().stream()
273	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
274	                && lastName.equalsIgnoreCase(existing.getLastName()))
275	            .count();
276	    }
277	
278	    /**
279	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
280	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
281	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
282	     * the names of every offending field, which the exception advice renders as a 400 response
283	     * with an {@code errors} array.
284	     *
285	     * @param ownerFieldsDto the submitted owner fields
286	     */
287	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
288	        List<String> missing = new ArrayList<>();
289	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
290	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
291	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
292	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
293	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
294	        if (!missing.isEmpty()) {
295	            throw new RequiredFieldsMissingException(missing);
296	        }
297	    }
298	
299	    private void addIfBlank(List<String> missing, String fieldName, String value) {
300	        if (value == null || value.isBlank()) {
301	            missing.add(fieldName);
302	        }
303	    }
304	
305	    /**
306	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
307	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
308	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
309	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
310	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
311	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
312	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
313	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
314	     *
315	     * @param telephone the submitted telephone value
316	     * @return the normalized E.164 telephone
317	     */
318	    private String normalizeTelephone(String telephone) {
319	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
320	        String e164;
321	        if (cleaned.startsWith("+")) {
322	            e164 = "+" + cleaned.substring(1);
323	        } else {
324	            String national = cleaned;
325	            if (national.startsWith("0")) {
326	                national = national.substring(1);
327	            }
328	            e164 = "+61" + national;
329	        }
330	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
331	            throw new InvalidFieldsException(List.of("telephone"));
332	        }
333	        return e164;
334	    }
335	
336	    /**
337	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
338	     * and a domain containing at least one dot, none of the parts holding whitespace or a
339	     * second {@code @}.
340	     */
341	    private static final java.util.regex.Pattern EMAIL_PATTERN =
342	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
343	
344	    /**
345	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
346	     * accepted and returned unchanged. When present it must be a syntactically valid address;
347	     * the value is stored and returned lower-cased. When present but invalid an
348	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
349	     * response naming the {@code email} field.
350	     *
351	     * @param email the submitted email value, or {@code null} when omitted
352	     * @return the lower-cased email, or {@code null} when none was supplied
353	     */
354	    private String normalizeEmail(String email) {
355	        if (email == null) {
356	            return null;
357	        }
358	        String trimmed = email.trim();
359	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
360	            throw new InvalidFieldsException(List.of("email"));
361	        }
362	        return trimmed.toLowerCase(java.util.Locale.ROOT);
363	    }
364	
365	    /**
366	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
367	     * The telephone is stored in its normalized E.164 form, so a plain equality check
368	     * against every owner's telephone compares E.164 values. When a match is found a
369	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
370	     * 409 Conflict response.
371	     *
372	     * @param telephone the normalized telephone of the owner being created
373	     */
374	    private void rejectDuplicateTelephone(String telephone) {
375	        boolean taken = this.clinicService.findAllOwners().stream()
376	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
377	        if (taken) {
378	            throw new DuplicateTelephoneException(telephone);
379	        }
380	    }
381	
382	    /**
383	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
384	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
385	     * for how that identity is compared). A request may bypass this rule by setting
386	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
387	     * When a household mate is found and the request did not opt in a
388	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
389	     * Conflict response.
390	     *
391	     * @param ownerFieldsDto the submitted owner fields
392	     */
393	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
394	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
395	            return;
396	        }
397	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
398	        if (taken) {
399	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
400	        }
401	    }
402	
403	    /**
404	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
405	     * set to {@code true}. The identifier is derived deterministically from the owner's
406	     * household identity (its {@code lastName} and {@code address}, see
407	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
408	     * the same stable value. The new owner receives that value, and any existing household mates
409	     * that do not yet carry it are updated so the whole household shares one identifier. When the
410	     * request did not opt in the owner is left without a household identifier.
411	     *
412	     * @param owner the newly created owner, mutated in place with its household identifier
413	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
414	     */
415	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
416	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
417	            return;
418	        }
419	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
420	        owner.setHouseholdId(householdId);
421	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
422	            if (!householdId.equals(mate.getHouseholdId())) {
423	                mate.setHouseholdId(householdId);
424	                this.clinicService.saveOwner(mate);
425	            }
426	        }
427	    }
428	
429	    /**
430	     * Derives the stable {@code householdId} shared by every owner in the household identified by
431	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
432	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
433	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
434	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
435	     *
436	     * @param lastName the household's last name
437	     * @param address the household's address
438	     * @return the deterministic household identifier
439	     */
440	    private String householdIdFor(String lastName, String address) {
441	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
442	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
443	        try {
444	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
445	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
446	            StringBuilder sb = new StringBuilder();
447	            for (int i = 0; i < 8; i++) {
448	                sb.append(String.format("%02X", digest[i]));
449	            }
450	            return "HH-" + sb;
451	        }
452	        catch (java.security.NoSuchAlgorithmException e) {
453	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
454	        }
455	    }
456	
457	    /**
458	     * Finds an existing owner that shares a household with the given {@code lastName} and
459	     * {@code address}. When several owners match, the first one encountered is returned.
460	     *
461	     * @param lastName the last name to match on
462	     * @param address the address to match on
463	     * @return the first owner sharing the household, or empty when none exists
464	     */
465	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
466	        return findHouseholdMates(lastName, address).stream().findFirst();
467	    }
468	
469	    /**
470	     * Finds every existing owner that shares a household with the given {@code lastName} and
471	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
472	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
473	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
474	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
475	     * every rule that reasons about households.
476	     *
477	     * @param lastName the last name to match on
478	     * @param address the address to match on
479	     * @return the owners sharing the household, in encounter order (possibly empty)
480	     */
481	    private List<Owner> findHouseholdMates(String lastName, String address) {
482	        String normalizedLastName = collapseWhitespace(lastName);
483	        String normalizedAddress = normalizeAddress(address);
484	        return this.clinicService.findAllOwners().stream()
485	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
486	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
487	            .toList();
488	    }
489	
490	    /**
491	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
492	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
493	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
494	     *
495	     * @param value the value to collapse, or {@code null}
496	     * @return the whitespace-collapsed value, never {@code null}
497	     */
498	    private String collapseWhitespace(String value) {
499	        if (value == null) {
500	            return "";
501	        }
502	        return value.trim().replaceAll("\\s+", " ");
503	    }
504	
505	    /**
506	     * Common street-type abbreviations expanded during address normalization, keyed by their
507	     * upper-cased token.
508	     */
509	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
510	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
511	
512	    /**
513	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
514	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
515	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
516	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
517	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
518	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
519	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
520	     * everywhere an address is stored or compared.
521	     *
522	     * @param address the submitted address value, or {@code null}
523	     * @return the normalized address, never {@code null}
524	     */
525	    private String normalizeAddress(String address) {
526	        if (address == null) {
527	            return "";
528	        }
529	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
530	        if (collapsed.isEmpty()) {
531	            return "";
532	        }
533	        String[] tokens = collapsed.split(" ");
534	        StringBuilder sb = new StringBuilder(collapsed.length());
535	        for (int i = 0; i < tokens.length; i++) {
536	            if (i > 0) {
537	                sb.append(' ');
538	            }
539	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
540	        }
541	        return sb.toString();
542	    }
543	}
