package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request tries to create an owner whose normalized telephone is
 * already used by another owner.
 * <p>
 * Signals a conflict with existing data so the {@link ExceptionControllerAdvice}
 * can surface it to the client as a {@code 409 Conflict} response.
 */
public class DuplicateTelephoneException extends RuntimeException {

    public DuplicateTelephoneException(String telephone) {
        super("An owner with telephone '" + telephone + "' already exists");
    }
}

